insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 'algerian-chakchouka', 'Chakchouka with peppers and eggs', 'Chakchouka aux poivrons et œufs', 'شكشوكة بالفلفل والبيض', 'Peppers and tomatoes simmered with cumin and paprika, with eggs poached right in the pan. A North African classic for breakfast or a light lunch.', 'Poivrons et tomates mijotés au cumin et au paprika, avec des œufs pochés directement dans la poêle. Un classique nord-africain pour le petit-déjeuner ou un déjeuner léger.', 'فلفل وطماطم مطهوة على نار هادئة مع الكمون والبابريكا، مع بيض مسلوق داخل المقلاة. طبق مغاربي كلاسيكي للفطور أو غداء خفيف.', 'https://images.unsplash.com/photo-1682622110419-b671026a4536?auto=format&fit=crop&w=1200&q=75', 'Alex Bayev on Unsplash', 2, 10, 25, array['breakfast', 'lunch']::text[], array['vegetarian', 'gluten_free']::text[], array['eggs']::text[], 331.9, 18.2, 29, 17.6, 7.7, true) on conflict (slug) do nothing;
