insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 1, 'Warm the olive oil in a wide pan over medium heat. Add the sliced onion and peppers and cook for 8 minutes until soft.', 'Chauffez l''huile d''olive dans une grande poêle à feu moyen. Ajoutez l''oignon et les poivrons émincés et faites cuire 8 minutes jusqu''à ce qu''ils soient tendres.', 'سخّن زيت الزيتون في مقلاة واسعة على نار متوسطة. أضف البصل والفلفل المقطع واطهه 8 دقائق حتى يلين.'),
  (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 2, 'Stir in the garlic, cumin and paprika and cook for 1 minute.', 'Ajoutez l''ail, le cumin et le paprika et faites cuire 1 minute.', 'أضف الثوم والكمون والبابريكا وقلّب لمدة دقيقة.'),
  (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 3, 'Add the crushed tomatoes, season with salt and pepper, and simmer for 10 minutes until thickened.', 'Ajoutez les tomates concassées, salez, poivrez et laissez mijoter 10 minutes jusqu''à épaississement.', 'أضف الطماطم المهروسة مع الملح والفلفل واتركها تغلي على نار هادئة 10 دقائق حتى تتكاثف.'),
  (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 4, 'Make four hollows in the sauce, crack an egg into each, cover and cook for 5–7 minutes until the whites are set.', 'Creusez quatre puits dans la sauce, cassez un œuf dans chacun, couvrez et faites cuire 5 à 7 minutes jusqu''à ce que les blancs soient pris.', 'اصنع أربع حفر في الصلصة واكسر بيضة في كل واحدة، ثم غطِّ واطهُ 5 إلى 7 دقائق حتى يتماسك البياض.'),
  (md5('nutritrack-recipe:algerian-chakchouka')::uuid, 5, 'Scatter with parsley and serve hot.', 'Parsemez de persil et servez chaud.', 'رشّ البقدونس وقدّمها ساخنة.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 'lentil-chickpea-harira', 'Lentil and chickpea harira (vegetarian)', 'Harira aux lentilles et pois chiches (végétarienne)', 'حريرة بالعدس والحمص (نباتية)', 'A vegetarian take on the spiced tomato, lentil and chickpea soup, finished with herbs and lemon. Traditional versions often add meat, which changes the nutrition.', 'Une version végétarienne de la soupe épicée aux tomates, lentilles et pois chiches, relevée d''herbes et de citron. Les versions traditionnelles contiennent souvent de la viande, ce qui modifie les valeurs nutritionnelles.', 'نسخة نباتية من شوربة الطماطم والعدس والحمص المتبلة، مع الأعشاب والليمون. غالبًا ما تحتوي النسخ التقليدية على اللحم، مما يغيّر القيم الغذائية.', 'https://images.unsplash.com/photo-1605909388460-74ec8b204127?auto=format&fit=crop&w=1200&q=75', 'Jezebel Rose on Unsplash', 6, 15, 45, array['lunch', 'dinner']::text[], array['vegan', 'vegetarian', 'dairy_free', 'high_fiber']::text[], array['gluten', 'celery']::text[], 271.3, 12.8, 43.6, 6.3, 8.2, true) on conflict (slug) do nothing;
