  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 12, md5('nutritrack-food:lemon_juice')::uuid, 'Lemon juice', 'Jus de citron', 'عصير ليمون', 2, 'tbsp', 30)
insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 1, 'Warm the oil in a large pot. Cook the chopped onion and celery for 6 minutes.', 'Chauffez l''huile dans une grande marmite. Faites revenir l''oignon et le céleri hachés 6 minutes.', 'سخّن الزيت في قدر كبير. اطهُ البصل والكرفس المفرومين 6 دقائق.'),
  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 2, 'Add the tomatoes, tomato paste, rinsed lentils and 1.5 litres of water. Season with ginger, turmeric, cinnamon, salt and pepper. Simmer for 30 minutes.', 'Ajoutez les tomates, le concentré, les lentilles rincées et 1,5 litre d''eau. Assaisonnez de gingembre, curcuma, cannelle, sel et poivre. Laissez mijoter 30 minutes.', 'أضف الطماطم ومعجون الطماطم والعدس المغسول و1.5 لتر من الماء. تبّل بالزنجبيل والكركم والقرفة والملح والفلفل. اتركها تغلي 30 دقيقة.'),
  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 3, 'Add the chickpeas and vermicelli and cook for 8 minutes.', 'Ajoutez les pois chiches et les vermicelles et faites cuire 8 minutes.', 'أضف الحمص والشعرية واطهُ 8 دقائق.'),
  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 4, 'Whisk the flour into a cup of cold water, pour it in while stirring, and simmer for 3 minutes until the soup thickens slightly.', 'Délayez la farine dans un verre d''eau froide, versez-la en remuant et laissez mijoter 3 minutes pour épaissir légèrement.', 'اخلط الدقيق في كوب من الماء البارد، واسكبه مع التحريك، واتركه 3 دقائق حتى تتكاثف الشوربة قليلًا.'),
  (md5('nutritrack-recipe:lentil-chickpea-harira')::uuid, 5, 'Stir in the chopped herbs and lemon juice just before serving.', 'Ajoutez les herbes hachées et le jus de citron juste avant de servir.', 'أضف الأعشاب المفرومة وعصير الليمون قبل التقديم مباشرة.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 'chicken-vegetable-couscous', 'Chicken and vegetable couscous', 'Couscous au poulet et aux légumes', 'كسكس بالدجاج والخضر', 'Tender chicken thighs with carrots, zucchini and chickpeas in a light tomato broth, served over fluffy couscous.', 'Des cuisses de poulet tendres avec carottes, courgettes et pois chiches dans un bouillon léger à la tomate, servies sur une semoule légère.', 'أفخاذ دجاج طرية مع الجزر والكوسة والحمص في مرق طماطم خفيف، تُقدَّم فوق كسكس هش.', 'https://images.unsplash.com/photo-1739217744880-472f59559cc5?auto=format&fit=crop&w=1200&q=75', 'Mourad Harkat on Unsplash', 4, 20, 50, array['lunch', 'dinner']::text[], array['high_protein', 'dairy_free']::text[], array['gluten']::text[], 640.7, 40, 74.8, 19.4, 9.1, true) on conflict (slug) do nothing;
