  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 6, md5('nutritrack-food:onion')::uuid, 'Onion, raw', 'Oignon, cru', 'بصل', 1, 'piece', 110),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 7, md5('nutritrack-food:tomato_paste')::uuid, 'Tomato paste', 'Concentré de tomate', 'معجون الطماطم', 1, 'tbsp', 16),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 8, md5('nutritrack-food:olive_oil')::uuid, 'Olive oil', 'Huile d''olive', 'زيت الزيتون', 2, 'tbsp', 27)
insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 1, 'Brown the chicken with the chopped onion in 1 tablespoon of oil in a large pot.', 'Faites dorer le poulet avec l''oignon haché dans 1 cuillère à soupe d''huile dans une grande marmite.', 'حمّر الدجاج مع البصل المفروم في ملعقة كبيرة من الزيت داخل قدر كبير.'),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 2, 'Add the tomato paste, ras el hanout, salt, pepper and 1 litre of water. Simmer for 25 minutes.', 'Ajoutez le concentré de tomate, le ras el hanout, du sel, du poivre et 1 litre d''eau. Laissez mijoter 25 minutes.', 'أضف معجون الطماطم ورأس الحانوت والملح والفلفل ولترًا من الماء. اتركه يغلي 25 دقيقة.'),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 3, 'Add the carrots, then after 10 minutes the zucchini and chickpeas. Cook until the vegetables are tender.', 'Ajoutez les carottes, puis après 10 minutes les courgettes et les pois chiches. Faites cuire jusqu''à ce que les légumes soient tendres.', 'أضف الجزر، وبعد 10 دقائق أضف الكوسة والحمص. اطهُ حتى تنضج الخضر.'),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 4, 'Pour 350 ml of boiling broth over the couscous with the remaining oil. Cover for 5 minutes, then fluff with a fork.', 'Versez 350 ml de bouillon bouillant sur la semoule avec le reste d''huile. Couvrez 5 minutes puis égrainez à la fourchette.', 'اسكب 350 مل من المرق المغلي فوق الكسكس مع بقية الزيت. غطّه 5 دقائق ثم فكّكه بالشوكة.'),
  (md5('nutritrack-recipe:chicken-vegetable-couscous')::uuid, 5, 'Serve the couscous topped with chicken, vegetables and a ladle of broth.', 'Servez la semoule garnie de poulet, de légumes et d''une louche de bouillon.', 'قدّم الكسكس مع الدجاج والخضر ومغرفة من المرق.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:greek-yogurt-berry-bowl')::uuid, 'greek-yogurt-berry-bowl', 'Greek yogurt bowl with berries and almonds', 'Bol de yaourt grec, fruits rouges et amandes', 'وعاء زبادي يوناني بالتوت واللوز', 'Thick yogurt topped with fresh berries, toasted almonds, chia and a little honey. Ready in five minutes.', 'Un yaourt épais garni de fruits rouges frais, d''amandes grillées, de chia et d''un filet de miel. Prêt en cinq minutes.', 'زبادي كثيف مع التوت الطازج واللوز المحمص وبذور الشيا وقليل من العسل. جاهز في خمس دقائق.', 'https://images.unsplash.com/photo-1610441009633-b6ca9c6d4be2?auto=format&fit=crop&w=1200&q=75', 'Eiliv Aceron on Unsplash', 1, 5, 0, array['breakfast', 'snack']::text[], array['vegetarian', 'gluten_free', 'high_protein']::text[], array['milk', 'tree_nuts']::text[], 298.6, 22.4, 34.1, 10, 7.1, true) on conflict (slug) do nothing;
