insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:lentil-feta-herb-salad')::uuid, 'lentil-feta-herb-salad', 'Lentil salad with feta and herbs', 'Salade de lentilles à la feta et aux herbes', 'سلطة العدس بالفيتا والأعشاب', 'Cooked lentils with cucumber, tomato, red onion, mint and parsley in a lemon dressing, topped with crumbled feta.', 'Des lentilles avec concombre, tomate, oignon rouge, menthe et persil dans une vinaigrette au citron, garnies de feta émiettée.', 'عدس مطبوخ مع الخيار والطماطم والبصل الأحمر والنعناع والبقدونس بصلصة الليمون، مع جبن الفيتا المفتت.', 'https://images.unsplash.com/photo-1623489254660-db5b367881d9?auto=format&fit=crop&w=1200&q=75', 'Mads Eneqvist on Unsplash', 4, 15, 0, array['lunch']::text[], array['vegetarian', 'gluten_free', 'high_fiber']::text[], array['milk']::text[], 327.8, 18.3, 37.6, 12.9, 13.3, true) on conflict (slug) do nothing;
