  (md5('nutritrack-recipe:lentil-feta-herb-salad')::uuid, 1, 'Dice the cucumber and tomatoes and finely slice the onion.', 'Coupez le concombre et les tomates en dés et émincez finement l''oignon.', 'قطّع الخيار والطماطم مكعبات وقطّع البصل شرائح رفيعة.'),
  (md5('nutritrack-recipe:lentil-feta-herb-salad')::uuid, 2, 'Whisk the olive oil and lemon juice with salt and pepper.', 'Fouettez l''huile d''olive et le jus de citron avec sel et poivre.', 'اخفق زيت الزيتون وعصير الليمون مع الملح والفلفل.'),
  (md5('nutritrack-recipe:lentil-feta-herb-salad')::uuid, 3, 'Toss the lentils, vegetables and herbs with the dressing.', 'Mélangez les lentilles, les légumes et les herbes avec la vinaigrette.', 'اخلط العدس والخضر والأعشاب مع الصلصة.'),
  (md5('nutritrack-recipe:lentil-feta-herb-salad')::uuid, 4, 'Crumble the feta over the top before serving.', 'Émiettez la feta par-dessus avant de servir.', 'فتّت جبن الفيتا فوقها قبل التقديم.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:baked-salmon-sweet-potato')::uuid, 'baked-salmon-sweet-potato', 'Baked salmon with sweet potato and broccoli', 'Saumon au four, patate douce et brocoli', 'سلمون في الفرن مع البطاطا الحلوة والبروكلي', 'A one-tray dinner: lemon-garlic salmon roasted alongside sweet potato wedges and broccoli.', 'Un dîner sur une seule plaque : saumon citron-ail rôti avec des quartiers de patate douce et du brocoli.', 'عشاء في صينية واحدة: سلمون بالليمون والثوم مشوي مع قطع البطاطا الحلوة والبروكلي.', 'https://images.unsplash.com/photo-1539136788836-5699e78bfc75?auto=format&fit=crop&w=1200&q=75', 'Ella Olsson on Unsplash', 2, 10, 30, array['dinner']::text[], array['pescatarian', 'gluten_free', 'dairy_free', 'high_protein']::text[], array['fish']::text[], 544.2, 39.6, 39.2, 26.3, 9.5, true) on conflict (slug) do nothing;
