insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:baked-salmon-sweet-potato')::uuid, 1, 'Heat the oven to 200 °C. Toss the sweet potato wedges with half the oil and roast for 15 minutes.', 'Préchauffez le four à 200 °C. Mélangez les quartiers de patate douce avec la moitié de l''huile et enfournez 15 minutes.', 'سخّن الفرن على 200 درجة. اخلط قطع البطاطا الحلوة مع نصف الزيت واشوِها 15 دقيقة.'),
  (md5('nutritrack-recipe:baked-salmon-sweet-potato')::uuid, 2, 'Add the broccoli and salmon to the tray. Brush the salmon with lemon juice, garlic and the remaining oil.', 'Ajoutez le brocoli et le saumon sur la plaque. Badigeonnez le saumon de jus de citron, d''ail et du reste d''huile.', 'أضف البروكلي والسلمون إلى الصينية. ادهن السلمون بعصير الليمون والثوم وبقية الزيت.'),
  (md5('nutritrack-recipe:baked-salmon-sweet-potato')::uuid, 3, 'Roast for 12–15 minutes, until the salmon flakes easily.', 'Enfournez 12 à 15 minutes, jusqu''à ce que le saumon s''effeuille facilement.', 'اشوِ 12 إلى 15 دقيقة حتى يتفتت السلمون بسهولة.')
