insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:chicken-quinoa-tahini-bowl')::uuid, 'chicken-quinoa-tahini-bowl', 'Chicken and quinoa bowl with tahini', 'Bol poulet-quinoa sauce tahini', 'وعاء الدجاج والكينوا بالطحينة', 'Sliced chicken breast over quinoa and spinach with cucumber, tomato and avocado, drizzled with lemon tahini.', 'Du blanc de poulet émincé sur du quinoa et des épinards, avec concombre, tomate et avocat, nappé de tahini au citron.', 'شرائح صدر دجاج فوق الكينوا والسبانخ مع الخيار والطماطم والأفوكادو، مع صلصة الطحينة بالليمون.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=1200&q=75', 'Anna Pelzer on Unsplash', 2, 15, 20, array['lunch', 'dinner']::text[], array['gluten_free', 'dairy_free', 'high_protein']::text[], array['sesame']::text[], 590.8, 50.4, 51.3, 21.2, 10.5, true) on conflict (slug) do nothing;
