insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:chicken-quinoa-tahini-bowl')::uuid, 1, 'Cook the quinoa according to the packet and let it cool slightly.', 'Faites cuire le quinoa selon le paquet et laissez tiédir.', 'اطهُ الكينوا حسب التعليمات واتركها تبرد قليلًا.'),
  (md5('nutritrack-recipe:chicken-quinoa-tahini-bowl')::uuid, 2, 'Grill or pan-cook the chicken until cooked through, then slice.', 'Faites griller ou poêler le poulet jusqu''à cuisson complète, puis tranchez-le.', 'اشوِ الدجاج أو اطهه في المقلاة حتى ينضج تمامًا، ثم قطّعه شرائح.'),
  (md5('nutritrack-recipe:chicken-quinoa-tahini-bowl')::uuid, 3, 'Whisk the tahini with lemon juice and 2 tablespoons of water.', 'Fouettez le tahini avec le jus de citron et 2 cuillères à soupe d''eau.', 'اخفق الطحينة مع عصير الليمون وملعقتين كبيرتين من الماء.'),
  (md5('nutritrack-recipe:chicken-quinoa-tahini-bowl')::uuid, 4, 'Build bowls with spinach, quinoa, vegetables and chicken, then drizzle with the sauce.', 'Composez les bols avec épinards, quinoa, légumes et poulet, puis nappez de sauce.', 'رتّب الأوعية بالسبانخ والكينوا والخضر والدجاج، ثم رشّ الصلصة.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:tofu-vegetable-stir-fry')::uuid, 'tofu-vegetable-stir-fry', 'Tofu and vegetable stir-fry with brown rice', 'Sauté de tofu et légumes au riz complet', 'توفو مقلي مع الخضر والأرز البني', 'Crispy tofu tossed with broccoli, pepper and carrot, served over brown rice.', 'Du tofu croustillant sauté avec brocoli, poivron et carotte, servi sur du riz complet.', 'توفو مقرمش مع البروكلي والفلفل والجزر، يُقدَّم فوق الأرز البني.', 'https://images.unsplash.com/photo-1564834724105-918b73d1b9e0?auto=format&fit=crop&w=1200&q=75', 'Ryan Kwok on Unsplash', 2, 15, 15, array['dinner']::text[], array['vegan', 'vegetarian', 'dairy_free', 'high_protein']::text[], array['soy']::text[], 522.9, 32.9, 55.7, 21.9, 10.6, true) on conflict (slug) do nothing;
