insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:tofu-vegetable-stir-fry')::uuid, 1, 'Press the tofu dry and cut it into cubes.', 'Pressez le tofu pour l''égoutter et coupez-le en cubes.', 'اضغط التوفو لإزالة الماء وقطّعه مكعبات.'),
  (md5('nutritrack-recipe:tofu-vegetable-stir-fry')::uuid, 2, 'Fry the tofu in the oil over high heat until golden, then set aside.', 'Faites dorer le tofu dans l''huile à feu vif, puis réservez.', 'اقلِ التوفو في الزيت على نار عالية حتى يتحمر، ثم ضعه جانبًا.'),
  (md5('nutritrack-recipe:tofu-vegetable-stir-fry')::uuid, 3, 'Stir-fry the vegetables and garlic for 5 minutes, then return the tofu with a splash of soy sauce if you like.', 'Faites sauter les légumes et l''ail 5 minutes, puis remettez le tofu avec un trait de sauce soja si vous le souhaitez.', 'قلّب الخضر والثوم 5 دقائق، ثم أعد التوفو مع قليل من صلصة الصويا إن رغبت.'),
  (md5('nutritrack-recipe:tofu-vegetable-stir-fry')::uuid, 4, 'Serve over the brown rice.', 'Servez sur le riz complet.', 'قدّمه فوق الأرز البني.')
insert into public.recipes (id, slug, title, title_fr, title_ar, description, description_fr, description_ar, image_url, image_credit, servings, prep_minutes, cook_minutes, meal_types, diet_tags, allergens, kcal_per_serving, protein_per_serving, carbs_per_serving, fat_per_serving, fiber_per_serving, is_public) values (md5('nutritrack-recipe:date-almond-energy-bites')::uuid, 'date-almond-energy-bites', 'Date and almond energy bites', 'Bouchées énergie dattes et amandes', 'كرات الطاقة بالتمر واللوز', 'No-bake bites of dates, almonds, oats and tahini. One serving is two bites.', 'Des bouchées sans cuisson aux dattes, amandes, avoine et tahini. Une portion correspond à deux bouchées.', 'كرات بدون طهي من التمر واللوز والشوفان والطحينة. الحصة الواحدة كرتان.', 'https://images.unsplash.com/photo-1716392916280-e17fb5a2c191?auto=format&fit=crop&w=1200&q=75', 'AnaCristina Smith on Unsplash', 6, 15, 0, array['snack']::text[], array['vegan', 'vegetarian', 'dairy_free']::text[], array['tree_nuts', 'sesame', 'gluten']::text[], 174.2, 4.6, 25.5, 7.5, 4.7, true) on conflict (slug) do nothing;
