insert into public.recipe_instructions (recipe_id, step, body, body_fr, body_ar) values
  (md5('nutritrack-recipe:date-almond-energy-bites')::uuid, 1, 'Blend the almonds and oats into a coarse crumb.', 'Mixez les amandes et l''avoine en une chapelure grossière.', 'اطحن اللوز والشوفان حتى يصبح فتاتًا خشنًا.'),
  (md5('nutritrack-recipe:date-almond-energy-bites')::uuid, 2, 'Add the dates, tahini and chia and blend until the mixture sticks together.', 'Ajoutez les dattes, le tahini et le chia et mixez jusqu''à ce que le mélange s''agglomère.', 'أضف التمر والطحينة والشيا واخلط حتى يتماسك الخليط.'),
  (md5('nutritrack-recipe:date-almond-energy-bites')::uuid, 3, 'Roll into 12 balls and chill for 20 minutes.', 'Formez 12 boules et réfrigérez 20 minutes.', 'شكّل 12 كرة وضعها في الثلاجة 20 دقيقة.')
